// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address nftContract, uint256 tokenId, bytes calldata data) public {
        vm.assume(caller != address(c));
        vm.assume(caller != address(0));
        vm.deal(caller, 0);

        bytes4 ret;
        vm.prank(caller);
        (bool success, bytes memory retData) = address(c).call(
            abi.encodeWithSignature("onERC721Received(address,address,uint256,bytes)", caller, nftContract, tokenId, data)
        );
        require(success, "call failed");
        ret = abi.decode(retData, (bytes4));

        assertTrue(ret == bytes4(0x150b7a02));
    }
}
